// ── Observe browser loading phases via Performance API ───────
window.addEventListener('load', () => {
  const nav = performance.getEntriesByType('navigation')[0];

  const phases = {
    dns:        nav.domainLookupEnd  - nav.domainLookupStart,
    tcp:        nav.connectEnd       - nav.connectStart,
    tls:        nav.connectEnd       - nav.secureConnectionStart,
    request:    nav.responseStart    - nav.requestStart,
    response:   nav.responseEnd      - nav.responseStart,
    domParsing: nav.domInteractive   - nav.responseEnd,
    subResources: nav.domContentLoadedEventStart - nav.domInteractive,
    loadEvent:  nav.loadEventEnd     - nav.loadEventStart,
    total:      nav.loadEventEnd     - nav.fetchStart,
  };

  console.table(
    Object.fromEntries(
      Object.entries(phases).map(([k, v]) => [k, `${v.toFixed(1)}ms`])
    )
  );
});

// ── Detect render-blocking scripts programmatically ──────────
// Check if a critical resource is loaded before DOMContentLoaded
document.addEventListener('DOMContentLoaded', () => {
  const resources = performance.getEntriesByType('resource');
  const blocking = resources.filter(r =>
    r.renderBlockingStatus === 'blocking'
  );
  if (blocking.length) {
    console.warn('Render-blocking resources:', blocking.map(r => r.name));
  }
});

// ── Resource hints: tell the browser what's coming ───────────
// In HTML <head>:
// <link rel="preconnect" href="https://fonts.googleapis.com">
// <link rel="dns-prefetch" href="https://cdn.example.com">
// <link rel="preload" as="script" href="/app.js">
// Or dynamically:
function preloadResource(href, as) {
  const link = document.createElement('link');
  link.rel  = 'preload';
  link.href = href;
  link.as   = as;
  document.head.appendChild(link);
}

// ── Defer vs Async explained with timing ─────────────────────
// <script src="a.js">        → blocks parser until downloaded + run
// <script src="a.js" defer>  → parallel download, run after HTML parsed
// <script src="a.js" async>  → parallel download, run immediately when ready
//
// Rule of thumb:
//  - defer  → scripts that need DOM (most app scripts)
//  - async  → independent scripts (analytics, ads)
//  - module → defer by default
console.log('script/defer/async demonstration — check your HTML <head>');

// ── Browser loading event timeline ───────────────────────────
//
// fetchStart
//   │── DNS lookup (domainLookupStart → domainLookupEnd)
//   │── TCP connect (connectStart → connectEnd)
//   │   └── TLS handshake (secureConnectionStart → connectEnd)
//   │── Request sent (requestStart)
//   │── First byte received (responseStart)   ← TTFB
//   │── Last byte received (responseEnd)
//   │── DOM parsing begins
//   │── DOMContentLoaded event fires (domContentLoadedEventStart)
//   │   └── defer scripts execute here
//   │── Sub-resources (images, iframes) load
//   └── load event fires (loadEventStart → loadEventEnd)
//
// Key milestones:
const EVENTS = {
  TTFB:             'responseStart - fetchStart    (server speed + network)',
  FCP:              'First Contentful Paint        (PerformanceObserver)',
  DOMContentLoaded: 'HTML parsed + deferred JS run',
  Load:             'All resources including images',
};

// ── Script loading strategies ─────────────────────────────────
const SCRIPT_STRATEGIES = [
  { attr: 'none (default)', parsesHTML: 'blocked', executes: 'immediately on download' },
  { attr: 'defer',          parsesHTML: 'parallel', executes: 'after DOM, in order' },
  { attr: 'async',          parsesHTML: 'parallel', executes: 'immediately, any order' },
  { attr: 'type=module',    parsesHTML: 'parallel', executes: 'deferred, in order' },
];

// ── HTTP version comparison ───────────────────────────────────
const HTTP_VERSIONS = {
  'HTTP/1.1': 'One request per connection; browsers open 6 parallel connections per origin',
  'HTTP/2':   'Multiplexed streams over one TCP; server push; header compression (HPACK)',
  'HTTP/3':   'QUIC (UDP); no head-of-line blocking; faster connection setup (0-RTT)',
};
